// TestRunExplainAuto_PostResolutionNotFoundSurfacesVerbatim reproduces the
// masked-error half of the `explain --generate` bug: when the target RESOLVES
// to a committed checkpoint but a later step fails with an error that merely
// wraps checkpoint.ErrCheckpointNotFound (in the field: "failed to save
// summary: checkpoint not found" against a backend missing the checkpoint),
// runExplainAuto must surface that failure — not misreport it via the commit
// fallback as `no checkpoint or commit found matching ...`.
//
// Vehicle: a ULID checkpoint written to the branch store is listable (List
// unions both backends) but unreadable (ULID reads route to refs only), so the
// prefix match succeeds and --generate's imported-checkpoint pre-read fails
// post-resolution with a wrapped ErrCheckpointNotFound.
func TestRunExplainAuto_PostResolutionNotFoundSurfacesVerbatim(t *testing.T) {
	repo, _ := runExplainAutoTestRepo(t)
	ctx := context.Background()

	ulidID := id.MustCheckpointID("01KVBJCWYA4YW6J5M9GP655HZN")
	require.NoError(t, checkpoint.NewGitStore(repo, checkpoint.DefaultV1Refs()).Write(ctx, checkpoint.Session{
		CheckpointID: ulidID,
		SessionID:    "session-stray-ulid",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte(`{"type":"user","message":{"content":[{"type":"text","text":"hello"}]}}` + "\n")),
		AuthorName:   "Test",
		AuthorEmail:  "test@example.com",
	}))

	var out, errOut bytes.Buffer
	err := runExplainAuto(ctx, &out, &errOut, ulidID.String(), true, false, false, false, true, false, false, 0)

	require.Error(t, err)
	require.ErrorContains(t, err, "failed to read checkpoint",
		"the post-resolution failure must surface as-is")
	require.NotContains(t, err.Error(), "no checkpoint or commit found",
		"a post-resolution failure must not be masked by the commit fallback")
}

